insert into public.partner_candidates(organization_id,id,profile,researched_at) values ('813ffcaf-835a-4e51-82db-3e411a978a20','sucarn','{"id":"sucarn","name":"Sucarn","country":"ES","city":"Barcelona","role":"Grossista de carnes para restauração e distribuição","email":"sucarn@sucarn.com","phone":"+34 93 335 01 30","contactUrl":"https://www.sucarn.es/","status":"Identificado · não contactado","sources":[{"url":"https://www.sucarn.es/","locator":"Empresa, Logística e Detalles de contacto","read":"Página consultada"}],"evidence":"Apresenta carnes nacionais e importadas, em fresco, congelado e precocinado, para restauração, coletividades e distribuição. Declara adaptar cortes e apresentações.","fit":{"chef":"initial","savoury":"initial","charcuterie":"no_evidence"},"reason":{"chef":"Investigar distribuição de cortes congelados para restauração.","savoury":"Investigar aceitação de porções e apresentações da gama.","charcuterie":"Sem oferta específica de charcutaria bovina congelada confirmada."},"check":"Confirmar interesse como distribuidor, produtos bovinos congelados aceites e condições de entrada de um novo fornecedor."}'::jsonb,'2026-10-14');
insert into public.partner_candidates(organization_id,id,profile,researched_at) values ('813ffcaf-835a-4e51-82db-3e411a978a20','mj','{"id":"mj","name":"MJ MEAT-CARN","country":"ES","city":"Llinars del Vallès, Barcelona","role":"Distribuidor e importador/exportador de carne congelada","email":"contact@mjmeat-carn.com","phone":"+34 938 45 33 90","contactUrl":"https://mjmeat-carn.com/","status":"Identificado · não contactado","sources":[{"url":"https://mjmeat-carn.com/","locator":"Company, Our products: Beef e rodapé de contactos","read":"Página consultada"}],"evidence":"Declara distribuição, importação e exportação de carne congelada e miudezas. Identifica bovino no portefólio e relações com produtores europeus.","fit":{"chef":"initial","savoury":"exploratory","charcuterie":"no_evidence"},"reason":{"chef":"Investigar compra e distribuição de cortes bovinos congelados.","savoury":"O bovino congelado é relevante; distribuição de porções e produto com marca permanece por confirmar.","charcuterie":"Sem evidência específica de charcutaria bovina congelada."},"check":"Distinguir interesse em matéria-prima a granel de interesse nas apresentações comerciais Trueborn."}'::jsonb,'2026-10-14');
insert into public.partner_candidates(organization_id,id,profile,researched_at) values ('813ffcaf-835a-4e51-82db-3e411a978a20','ambar','{"id":"ambar","name":"Ambar Foods","country":"ES","city":"Murcia","role":"Trader de carnes congeladas","email":"andreybarquero@ambarfoods.es","phone":"+34 868 078 638","contactUrl":"https://ambarfoods.es/en/","status":"Identificado · não contactado","sources":[{"url":"https://ambarfoods.es/en/","locator":"Products: Beef, International Logistics e Contact us","read":"Página consultada"}],"evidence":"Apresenta bovino congelado para comércio internacional e coordenação logística de cadeia de frio.","fit":{"chef":"initial","savoury":"exploratory","charcuterie":"no_evidence"},"reason":{"chef":"Investigar intermediação e distribuição de cortes congelados.","savoury":"Não foi demonstrada distribuição de porções ou apresentações de retalho.","charcuterie":"Sem oferta específica de charcutaria bovina congelada confirmada."},"check":"Confirmar se compra por conta própria ou atua como intermediário, e os canais servidos."}'::jsonb,'2026-10-14');
insert into public.partner_candidates(organization_id,id,profile,researched_at) values ('813ffcaf-835a-4e51-82db-3e411a978a20','fn','{"id":"fn","name":"FN Global Meat","country":"NL","city":"Dordrecht","role":"Importador e grossista internacional de carne","email":"sales@fnglobalmeat.com","phone":"+31 78 6531 840","contactUrl":"https://www.fnglobalmeat.com/en/contact/","status":"Identificado · não contactado","sources":[{"url":"https://www.fnglobalmeat.com/en/about-us/","locator":"Welcome, Specialist, Warehousing & distribution","read":"Página consultada"},{"url":"https://www.fnglobalmeat.com/en/contact/","locator":"Sales Department","read":"Página consultada"}],"evidence":"Declara importação de bovino refrigerado e congelado, fornecimento a catering, grossistas e retalho, armazenamento congelado e serviços de etiquetagem.","fit":{"chef":"initial","savoury":"initial","charcuterie":"no_evidence"},"reason":{"chef":"Investigar os canais Food Service e de grossistas para cortes.","savoury":"O retalho e a etiquetagem são sinais de canal relevante; confirmar interesse em marca Trueborn.","charcuterie":"Fornecimento de carne à indústria não comprova compra de charcutaria acabada."},"check":"Confirmar interesse em origem portuguesa, aceitação da marca e formatos de fornecimento."}'::jsonb,'2026-10-14');
insert into public.partner_candidates(organization_id,id,profile,researched_at) values ('813ffcaf-835a-4e51-82db-3e411a978a20','knh','{"id":"knh","name":"Kühne + Heitz","country":"NL","city":"Dordrecht","role":"Importador/exportador e distribuidor de congelados","email":"sales@knh.nl","phone":"+31 78 632 1222","contactUrl":"https://www.knh.nl/","status":"Identificado · não contactado","sources":[{"url":"https://www.knh.nl/","locator":"Who We Are, Distribution Regions e Contact Us","read":"Página consultada"},{"url":"https://www.knh.nl/meat/","locator":"Frozen Beef: cuts, steaks e boneless cubes","read":"Conteúdo indexado consultado; abertura da página limitada"}],"evidence":"A página principal declara comércio e distribuição de congelados. A página de carne indexada identifica cortes, steaks e cubos bovinos congelados.","fit":{"chef":"initial","savoury":"initial","charcuterie":"no_evidence"},"reason":{"chef":"Investigar fornecimento de cortes e cubos congelados.","savoury":"Steaks são um sinal de adequação; as apresentações Trueborn e a marca precisam de validação.","charcuterie":"Não transferir a oferta de enchidos de outra espécie para charcutaria bovina."},"check":"Reconfirmar o catálogo bovino atual, mercado de destino e preferência por marca do fornecedor ou marca própria."}'::jsonb,'2026-10-14');
insert into public.partner_candidates(organization_id,id,profile,researched_at) values ('813ffcaf-835a-4e51-82db-3e411a978a20','ferwerda','{"id":"ferwerda","name":"Ferwerda Worldwide Meat Suppliers","country":"NL","city":"Rotterdam","role":"Importador/exportador de carnes e congelados","email":"info@ferwerda.nl","phone":"+31 10 298 22 22","contactUrl":"https://www.ferwerda.nl/en/","status":"Identificado · não contactado","sources":[{"url":"https://www.ferwerda.nl/en/","locator":"Get to know us, Import & Export e Contact","read":"Página consultada"},{"url":"https://www.ferwerda.nl/en/products/processed-meat/","locator":"All Processed meat products","read":"Página consultada"}],"evidence":"Declara compra de bovino e importação de carnes da Europa e de outras origens, com armazém de frio em Rotterdam. O portefólio de processados inclui enchidos e produtos fumados.","fit":{"chef":"initial","savoury":"exploratory","charcuterie":"exploratory"},"reason":{"chef":"Investigar compra e distribuição de cortes congelados.","savoury":"Confirmar se trabalha as apresentações acabadas e com marca.","charcuterie":"A oferta de enchidos justifica exploração, mas não comprova espécie bovina nem conservação congelada."},"check":"Para charcutaria, confirmar primeiro aceitação de bovino congelado e canais; não assumir equivalência aos processados apresentados."}'::jsonb,'2026-10-14');
insert into public.partner_candidates(organization_id,id,profile,researched_at) values ('813ffcaf-835a-4e51-82db-3e411a978a20','eurobeef','{"id":"eurobeef","name":"Euro-Beef Fleischhandels","country":"DE","city":"Kerpen","role":"Comerciante de especialidades de carne","email":null,"phone":"+49 2237 9281 0","contactUrl":"https://euro-beef.de/","status":"Identificado · não contactado","sources":[{"url":"https://euro-beef.de/","locator":"Startseite, Telefon e Adresse","read":"Página consultada"},{"url":"https://euro-beef.de/produkte/","locator":"Produkte: Rind","read":"Página consultada"}],"evidence":"Declara comércio de especialidades refrigeradas e ultracongeladas. Identifica roastbeef, filete, entrecôte e outros cortes bovinos.","fit":{"chef":"initial","savoury":"initial","charcuterie":"no_evidence"},"reason":{"chef":"Investigar os cortes bovinos comercializados em regime congelado.","savoury":"Os cortes apresentados são relevantes; confirmar aceitação das porções e marca.","charcuterie":"Sem oferta de charcutaria bovina congelada identificada."},"check":"Confirmar quais cortes são congelados, canais servidos e abertura a novos fornecedores. Email não recolhido; telefone publicado disponível."}'::jsonb,'2026-10-14');
insert into public.partner_candidates(organization_id,id,profile,researched_at) values ('813ffcaf-835a-4e51-82db-3e411a978a20','andupez','{"id":"andupez","name":"Andupez","country":"DE","city":"Berlim","role":"Importador e grossista de especialidades mediterrânicas","email":"verkauf@andupez.de","phone":"+49 30 398982 0","contactUrl":"https://www.andupez.de/kunde-werden","status":"Identificado · não contactado","sources":[{"url":"https://www.andupez.de/kunde-werden","locator":"Sortimento, origem dos produtos, serviço gastronómico e Kontakt","read":"Página consultada"}],"evidence":"Declara importação direta, incluindo Portugal, oferta de bovino e produtos de charcutaria, e distribuição B2B na Alemanha.","fit":{"chef":"exploratory","savoury":"exploratory","charcuterie":"exploratory"},"reason":{"chef":"A oferta bovina justifica uma consulta; conservação congelada desses cortes não confirmada.","savoury":"Investigar apresentações e canais gastronómicos; não há adequação específica comprovada.","charcuterie":"O canal mediterrânico é uma hipótese; oferta de charcutaria bovina congelada não confirmada."},"check":"Confirmar primeiro interesse em bovino e charcutaria congelados de origem portuguesa, sem assumir que a atual charcutaria tem a mesma espécie."}'::jsonb,'2026-10-14');
insert into public.research_snapshots(organization_id,id,payload,researched_at) values ('813ffcaf-835a-4e51-82db-3e411a978a20','market-research-v1','{"version":1,"researchedAt":"2026-10-14","referenceYear":2024,"assumption":{"state":"Congelado","source":"Indicação direta do utilizador em 14/10/2026","scope":["chef","savoury","charcuterie"]},"sources":{"beef24":{"name":"WITS / UN Comtrade · HS 020230 · 2024","url":"https://wits.worldbank.org/trade/comtrade/en/country/ALL/year/2024/tradeflow/Imports/partner/WLD/product/020230"},"beef23":{"name":"WITS / UN Comtrade · HS 020230 · 2023","url":"https://wits.worldbank.org/trade/comtrade/en/country/ALL/year/2023/tradeflow/Imports/partner/WLD/product/020230"},"bone24":{"name":"WITS / UN Comtrade · HS 020220 · 2024","url":"https://wits.worldbank.org/trade/comtrade/en/country/ALL/year/2024/tradeflow/Imports/partner/WLD/product/020220"},"char24":{"name":"WITS / UN Comtrade · HS 160100 · 2024","url":"https://wits.worldbank.org/trade/comtrade/en/country/ALL/year/2024/tradeflow/Imports/partner/WLD/product/160100"},"pt24":{"name":"WITS / UN Comtrade · Exportações de Portugal · HS 020230 · 2024","url":"https://wits.worldbank.org/trade/comtrade/en/country/PRT/year/2024/tradeflow/Exports/partner/ALL/product/020230"},"makro":{"name":"Makro Espanha · carne congelada para restauração","url":"https://www.makro.es/productos/congelados/carnes"},"metroFR":{"name":"METRO França · oferta de bovino para profissionais","url":"https://www.metro.fr/metro/univers-produits/boucherie/viande-boeuf"},"sligro":{"name":"Sligro Países Baixos · bovino, incluindo filtro congelados","url":"https://www.sligro.nl/c/002.html"},"metroIT":{"name":"METRO Itália · carne bovina congelada","url":"https://www.metro.it/ingrosso/surgelati/carne-surgelata"},"metroDE":{"name":"METRO Alemanha · bovino argentino e cortes para gastronomia","url":"https://www.metro.de/information-services/eigenmarken/metro-premium/argentinisches-rind"},"egeturk":{"name":"Egetürk Alemanha · salsichas de bovino","url":"https://www.egetuerk.de/egetuerk/wuerstchen/"},"uk":{"name":"GOV.UK · importação de produtos de origem animal","url":"https://www.gov.uk/guidance/import-or-move-food-and-drink-from-the-eu-and-northern-ireland-to-great-britain"},"sa":{"name":"SFDA · requisito de certificação Halal para carne","url":"https://sfda.gov.sa/en/faq/what-are-products-require-halal-certificate"}},"markets":[{"code":"ES","beef2024":171314.32,"beef2023":145454.17,"bone2024":24358.84,"char2024":135683.75,"portugalBeef2024":6558.04,"phase":"Primeira abordagem","channels":["makro"],"finding":"Existe oferta pública de bovino congelado para HoReCa na Makro e um fluxo português documentado nesta categoria.","risk":"A presença de oferta concorrente não demonstra interesse em Trueborn. Para charcutaria congelada, confirmar um canal específico.","next":"Pesquisar distribuidores de congelados e operadores de restauração que trabalhem cortes e porções."},{"code":"FR","beef2024":453553.29,"beef2023":475786.24,"bone2024":12675.65,"char2024":519863.48,"portugalBeef2024":1572.86,"phase":"Primeira abordagem","channels":["metroFR"],"finding":"Mercado de importação relevante e oferta profissional de bovino na METRO. Portugal já exportava a categoria para França.","risk":"O canal consultado comprova oferta de bovino; não comprova todos os cortes congelados ou interesse de compra. A procura de charcutaria bovina congelada permanece por confirmar.","next":"Procurar grossistas de congelados e validar canais Food Service antes de considerar retalho."},{"code":"NL","beef2024":273041.93,"beef2023":245336.85,"bone2024":8235.34,"char2024":360386.58,"portugalBeef2024":1824.01,"phase":"Primeira abordagem","channels":["sligro"],"finding":"A Sligro apresenta categoria de bovino com filtro para congelados. Há fluxo português documentado.","risk":"Importações podem servir consumo interno ou redistribuição. O total não identifica margem, canal final ou oportunidade Trueborn.","next":"Mapear grossistas e separar compradores para consumo local de operadores de redistribuição."},{"code":"DE","beef2024":367098.25,"beef2023":333472.78,"bone2024":34203.04,"char2024":915434.71,"portugalBeef2024":316.72,"phase":"Primeira abordagem","channels":["metroDE","egeturk"],"finding":"Oferta profissional de cortes bovinos e concorrente alemão de salsichas de bovino identificados.","risk":"A concorrência existe. As salsichas Egetürk consultadas são apresentadas em lata e como Halal: não equivalem ao congelado Trueborn nem certificam a marca.","next":"Distinguir canais gastronómicos, grossistas de congelados e nichos de charcutaria bovina."},{"code":"IT","beef2024":307209.78,"beef2023":288604.41,"bone2024":22907.07,"char2024":100298.13,"portugalBeef2024":695.42,"phase":"Primeira abordagem","channels":["metroIT"],"finding":"A METRO Itália apresenta cortes bovinos congelados. Portugal já exportava a categoria para Itália.","risk":"Oferta de cortes não comprova procura da marca nem adequação de todas as apresentações Savoury.","next":"Priorizar distribuidores Food Service de cortes congelados e testar a adequação das porções."},{"code":"BE","beef2024":88086.11,"beef2023":81343.21,"bone2024":6188.34,"char2024":358070.3,"portugalBeef2024":129.98,"phase":"Exploração de charcutaria","channels":[],"finding":"O valor importado da categoria ampla de enchidos justifica aprofundar a pesquisa de charcutaria.","risk":"Não foi identificado nesta ronda um comprador de charcutaria bovina congelada. A categoria estatística agrega espécies e regimes de conservação.","next":"Encontrar distribuidores especializados e confirmar aceitação de apresentação congelada."},{"code":"GB","beef2024":442383.89,"beef2023":355207.97,"bone2024":6619.82,"char2024":996544.89,"portugalBeef2024":285.82,"phase":"Exploração condicionada","channels":["uk"],"finding":"Importações elevadas nas categorias consultadas. A orientação oficial de Great Britain exige verificar condições e documentação por produto.","risk":"Dados estatísticos são do Reino Unido; a orientação citada aplica-se a Great Britain. Não foi confirmada elegibilidade de estabelecimento/produto Trueborn.","next":"Pesquisar importadores de congelados e verificar condições oficiais antes de uma abordagem comercial."},{"code":"SA","beef2024":488179.2,"beef2023":339148.71,"bone2024":131707.34,"char2024":83841.98,"portugalBeef2024":null,"phase":"Segunda fase","channels":["sa"],"finding":"Escala relevante de importação de bovino congelado. A SFDA identifica certificação Halal como requisito para carne e produtos.","risk":"Não foi comprovada certificação Trueborn nem elegibilidade para este destino. O valor português não foi recolhido, não é zero.","next":"Verificar viabilidade de acesso e certificação antes de investir em prospeção de compradores."},{"code":"JP","beef2024":1536464.32,"beef2023":1354745.39,"bone2024":null,"char2024":131593,"portugalBeef2024":null,"phase":"Segunda fase","channels":[],"finding":"Mercado de maior escala para bovino congelado sem osso entre os nove países desta pesquisa.","risk":"Dimensão não demonstra acesso viável para Trueborn, capacidade logística ou competitividade. Canais e condições específicas ainda não investigados.","next":"Aprofundar elegibilidade, importadores e logística antes de priorizar investimento comercial."}],"shortlists":{"chef":[{"code":"ES","reason":"Começar pelo fluxo português mais elevado entre os países analisados e pela oferta pública de bovino congelado para HoReCa."},{"code":"NL","reason":"Investigar grossistas de congelados, com categoria de bovino identificada e fluxo português existente."},{"code":"FR","reason":"Aprofundar distribuição profissional num mercado com importações relevantes e fluxo português."},{"code":"IT","reason":"Testar cortes para cozinhas profissionais num canal que apresenta bovino congelado."},{"code":"DE","reason":"Investigar distribuidores de cortes bovinos, comparando com a oferta argentina já apresentada no canal profissional."}],"savoury":[{"code":"ES","reason":"Explorar porções e hambúrgueres congelados nos canais profissionais; não assumir acesso ao retalho."},{"code":"DE","reason":"Comparar cortes e apresentações com a oferta premium profissional identificada."},{"code":"FR","reason":"Investigar compradores de cortes e porções, distinguindo a procura agregada de uma oportunidade concreta."},{"code":"IT","reason":"Validar a adequação dos cortes Savoury ao canal profissional de congelados identificado."},{"code":"NL","reason":"Pesquisar grossistas que ofereçam bovino congelado e porções; confirmar formatos aceites."}],"charcuterie":[{"code":"DE","reason":"Começar onde foi identificado um concorrente de charcutaria bovina; comprovar separadamente procura de produto congelado."},{"code":"FR","reason":"Investigar Food Service especializado, usando o total de enchidos apenas como sinal de contexto."},{"code":"NL","reason":"Pesquisar distribuidores especializados; validar cadeia de frio e aceitação da charcutaria congelada."},{"code":"BE","reason":"Aprofundar um mercado relevante da categoria ampla; ainda sem canal específico confirmado."},{"code":"GB","reason":"Pesquisar a categoria de maior valor entre os países analisados, condicionando a abordagem à verificação de acesso."}]}}'::jsonb,'2026-10-14');
insert into public.research_snapshots(organization_id,id,payload,researched_at) values ('813ffcaf-835a-4e51-82db-3e411a978a20','catalogue-references-v1','{"documents":[{"id":"C1","filename":"The Chef Solutions_True Born_2025.pdf.pdf","pages":3,"sha256":"7fb77773b6c24284aa17ded652ba119dac0d43f8026b2e52a5267419b4d849ee","checkedAt":"2026-10-14","scopePages":[1],"excludedPages":[2,3]},{"id":"C2","filename":"The Savoury Cuts_True Born_2025.pdf.pdf","pages":5,"sha256":"f3cf4e69c8167af5d198ca2956378c8b122ee12aa8d8b3ca67968e2e1f1fd743","checkedAt":"2026-10-14","scopePages":[1,2],"excludedPages":[3,4,5]}],"profiles":{"chef":{"source":"C1","page":1,"heading":"Beef · The Chef Solutions","channels":[],"products":["Sirloin Cap","Acém","Tip of the Sirloin","Sirloin","Filé Mignon","Rump","Rump Steak","Beef Rump","Cow’s Brisket","Rib Fillet","Palette","Top Round","Patinho","Shoulder or Palette","Palette Racket","Back Muscle","Fraldinha ou Aba","Cow’s Belly","Front Muscle","Lagarto","Soft Muscle"],"note":"Nomes transcritos das legendas. “Top Round” aparece em duas posições; “Palette” e “Shoulder or Palette” foram preservados sem resolver possíveis equivalências. A lista não representa uma contagem de artigos comerciais.","claims":["O catálogo declara animais nascidos em Portugal e criados no Alentejo.","O catálogo declara alimentação adaptada e práticas de bem-estar animal."],"presentation":"Imagens de cortes embalados. O selo “Frozen is the true freshness” está visível; não fornece temperatura nem prazo de conservação.","missing":["Preços e condições comerciais","Pesos, dimensões e códigos de artigo","Ingredientes completos e alergénios","Certificações e elegibilidade de exportação","Códigos pautais por produto"]},"savoury":{"source":"C2","page":1,"heading":"Beef · The Savoury Cuts","channels":[],"products":["Filet Mignon","Ribeye Steak","New York Steak","Rump Steak","Ranch Steak","Petite Chuck Steak","Picanha Steak","Beefs Cubes","Strogonoff","Burguer Gourmet","Mini Beefburger","Finest Minced Beef","Chuleton","Tomahawk","T-Bone"],"note":"Nomes conferidos visualmente nas embalagens, mantendo a grafia do documento, incluindo “Beefs Cubes” e “Burguer Gourmet”. A apresentação não informa códigos de artigo nem formatos técnicos completos.","claims":["O catálogo declara criação de bovinos ao ar livre no Alentejo e práticas de bem-estar animal."],"presentation":"Doze apresentações em bandeja e três cortes com os nomes Chuleton, Tomahawk e T-Bone. O selo “Frozen is the true freshness” está visível; não substitui a ficha técnica.","missing":["Preços e condições comerciais","Pesos, dimensões e códigos de artigo","Ingredientes completos e alergénios","Certificações e elegibilidade de exportação","Códigos pautais por produto"]},"charcuterie":{"source":"C2","page":2,"heading":"Charcuterie · Collection","channels":["Food Service","Retail"],"products":["Chouriço","Linguiça delgada","Salsichão","Salsichão delgado","Paio"],"note":"Cinco nomes apresentados em Food Service e em Retail. As embalagens identificam “Bovino”; a página não permite concluir a percentagem de carne bovina, todos os ingredientes ou o material da tripa.","claims":["A página apresenta a gama como charcutaria de bovino.","O catálogo declara animais nascidos em Portugal, criados no Alentejo, alimentação adaptada e práticas de bem-estar animal."],"presentation":"Duas apresentações comerciais por nome: Food Service e Retail. Não há pesos ou códigos de artigo legíveis que permitam definir os formatos técnicos.","missing":["Preços e condições comerciais","Pesos, dimensões e códigos de artigo","Ingredientes completos e alergénios","Certificações e elegibilidade de exportação","Códigos pautais por produto"]}},"storage":{"state":"Congelado","source":"Indicação do utilizador em 14/10/2026","scope":["chef","savoury","charcuterie"]}}'::jsonb,'2026-10-14');
